#define assert(x) ((void)0)

template <class T>
class list
{
    struct node
    {
        node *next;
        node *previous;
        T value;
    };

    int field0;
    int field1;
    node *sentinel;

public:
    class iterator
    {
        node *current;
    public:
        iterator() {}
        iterator(node *n) : current(n) {}
        T &operator*() const { return current->value; }
        iterator &operator++() { current = current->next; return *this; }
        bool operator!=(const iterator &right) const { return current != right.current; }
        node *base() const { return current; }
    };

    class reverse_iterator
    {
        iterator current;
    public:
        reverse_iterator() {}
        reverse_iterator(iterator i) : current(i) {}
        T &operator*() const { iterator i = current; return i.base()->previous->value; }
        reverse_iterator &operator++() { current = iterator(current.base()->previous); return *this; }
        bool operator!=(const reverse_iterator &right) const { return current != right.current; }
    };

    iterator begin() { return iterator(sentinel->next); }
    iterator end() { return iterator(sentinel); }
    reverse_iterator rbegin() { return reverse_iterator(end()); }
    reverse_iterator rend() { return reverse_iterator(begin()); }
    bool empty() const { return sentinel->next == sentinel; }
};

struct TrickData
{
    int flags;
    char padding[84];
};
extern TrickData GTrickList[];

class IGOFrontEnd
{
public:
    void OnTrickChange(int playerIdx, bool updateText);
};

struct FrontEndManager
{
    IGOFrontEnd *IGO;
};
extern FrontEndManager frontendmanager;

class SpecialMeter
{
public:
    void Increase(float amount);
};

class ScoringManager
{
public:
    enum ATTRIBUTE
    {
        ATTR_DIST_LIP,
        ATTR_DIST_MOUTH,
        ATTR_TIME_TOTAL,
        ATTR_TIME_DELTA,
        ATTR_TO_FAKEY,
        ATTR_FROM_FLOATER,
        ATTR_HOP,
        ATTR_LAME,
        ATTR_AT_MOUTH,
        ATTR_NUM_SPINS_DELTA,
        ATTR_NUM_SPINS_TOTAL,
        ATTR_LANDING,
        ATTR_FLAG_SET,
        ATTR_FLAG_UNSET
    };

    class Trick
    {
    public:
        enum TYPE { TYPE_TRICK, TYPE_GAP };
        TYPE type;
        int index;
        int flags;
        float time;
        int numSpins;
        float mouthDist;
        float lipDist;
        int repetitions;
    };
    typedef list<Trick> TrickList;

    class Series
    {
        void *levelTricks;
    public:
        TrickList tricks;
        int numSpins;
        int landing;
        int flags;
    };
    typedef list<Series> SeriesList;

    class Chain
    {
        void *levelTricks;
        float multAdder;
    public:
        SeriesList series;
        float GetSickness() const;
    };

private:
    char padding0[12];
    int playerIdx;
    SpecialMeter *specialMeter;
    char padding1[408];
    Chain chain;

public:
    void UpdateLastTrick(const ATTRIBUTE attr, const int i, const int flags = 0);
};

void ScoringManager::UpdateLastTrick(const ScoringManager::ATTRIBUTE attr, const int i, const int flags)
{
	float								oldSickness;
	TrickList::reverse_iterator			tit;
	SeriesList::reverse_iterator		sit;

	// Probably only need to search the last series.
	// No point in checking multiple series...?

	// Search backwards through the series.
	for (sit = chain.series.rbegin(); sit != chain.series.rend(); ++sit)
	{
		if ((*sit).tricks.empty())
			continue;

		// Search backwards for the last non-gap trick in this series that matches the specified
		// type and flags.
		for (tit = (*sit).tricks.rbegin(); tit != (*sit).tricks.rend(); ++tit)
		{
			// Ignore gaps.
			if ((*tit).type != Trick::TYPE_TRICK)
				continue;

			// Optional requirement: flag match.
			if (flags && ((GTrickList[(*tit).index].flags & flags) != flags))
				continue;

			oldSickness = chain.GetSickness();

			switch (attr)
			{
			case ATTR_NUM_SPINS_DELTA :
				(*tit).numSpins += i;
				frontendmanager.IGO->OnTrickChange(playerIdx, false);
				break;
			case ATTR_NUM_SPINS_TOTAL :
				(*tit).numSpins = i;
				frontendmanager.IGO->OnTrickChange(playerIdx, false);
				break;
			default : assert(0);
			}

			specialMeter->Increase(chain.GetSickness()-oldSickness);

			return;
		}
	}
}
